from pyspark.sql import functions as F, Window
from decimal import Decimal

def run(spark, tables):
    policy_df = tables['policy']
    
    # Step 1: Count policies and sum claims for each region
    region_stats = policy_df.groupBy('Region').agg(
        F.count('IDpol').alias('Policies'),
        F.sum('ClaimNb').alias('Claims')
    )
    
    # Step 2: Rank regions by claims in descending order
    ranked_regions = region_stats.withColumn(
        'ClaimRank',
        F.dense_rank().over(Window.orderBy(F.desc('Claims')))
    )
    
    return ranked_regions
